public int maxProfit(int[] prices) {
  int maxProfit =0;
  int cp = prices[0];


  for(int i =1;i<prices.length;i++)
    {
        cp = Math.min(cp,prices[i]);

        int profit = prices[i]-cp;

        if(maxProfit<profit){
            maxProfit= profit;
        }
    }

    return maxProfit;
}
